"use client";

import { loadFont as loadInter } from "@remotion/google-fonts/Inter";
import { type CSSProperties, useLayoutEffect, useRef, useState } from "react";
import {
  AbsoluteFill,
  continueRender,
  delayRender,
  Easing,
  getRemotionEnvironment,
  interpolate,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";
import {
  enterOffset,
  normalizeEffects,
  resolveEasing,
  TEXT_REVEAL_DEFAULTS,
  type TextRevealDirection,
  type TextRevealEasing,
  type TextRevealEffect,
} from "@/components/snap-cn/text-reveal";
import {
  mixOklch,
  type SnapCnTheme,
  useSnapCnTheme,
  withAlpha,
} from "@/lib/snap-cn-ui";
import {
  COOL_SPAN,
  CUT_AT,
  CUT2_AT,
  EXIT_COEFF,
  EXIT_FROM,
  EXIT_RATIO,
  FINAL_CHAR_HOLD,
  FLOOD_STAGE_FRAMES,
  FRAMES_PER_CHAR,
  GLYPH_ENTER_SCALE,
  GLYPH_ENTER_TINT,
  GLYPH_SETTLE_FRAMES,
  MORPH_FROM,
  MORPH_TO,
  SLIDE_BEZIER,
  SLIDE_FROM,
  SLIDE_TO,
  TYPE_START,
} from "./timeline";

const { fontFamily: SANS } = loadInter("normal", {
  weights: ["400", "700"],
  subsets: ["latin"],
});

export interface TypeMorphProps {
  /**
   * The line as it is typed. Everything up to and including `lead` is cut away
   * once typing finishes, which is what leaves the emphasis alone on screen.
   */
  lead?: string;
  /** The emphasised tail of the typed line — this is what survives the cut. */
  emphasis?: string;
  /** What the emphasis morphs into, letter by letter. */
  morphTo?: string;
  /**
   * What is left after the second cut. Empty ends the beat on the bare flood.
   */
  finally_?: string;
  /**
   * Whether the final phrase survives into the flood.
   *
   * The reference carries it across; off is the cleaner ending, and it is the
   * default because a word sitting on a full-bleed colour for four frames reads
   * as a leftover rather than as a beat.
   */
  wordOnFlood?: boolean;
  /** Caret and freshly-typed glyphs. Defaults to the theme's accent. */
  accent?: string;
  /**
   * Two flat colours to flood the frame with at the end, or `false` to end on
   * paper — the default.
   *
   * The reference floods; off is the quieter ending and the one that composes,
   * because a beat that hands the next scene a full-bleed colour has decided
   * what that scene opens on.
   *
   * Two flat colours rather than a ramp: the reference arrives at 99% frame
   * coverage inside a single frame and then steps once. A crossfade between them
   * would put a half-transparent wash over the type for several frames, and
   * there is no reading of that except the screen dimming.
   */
  flood?: [string, string] | false;
  /**
   * The page.
   *
   * Defaults to the theme's background so the component belongs in whatever
   * project installs it. The reference's paper is a plain near-white (#f7f7f7 to
   * #fafafa across the beat), not the warm off-white the token carries, so the
   * preview passes its own.
   */
  background?: string;
  /** The type. Defaults to the theme's foreground. */
  ink?: string;
  /**
   * The typed line's entrance is `text-reveal`'s, not a second animator.
   *
   * These are that component's own settings under its own names, defaulting to
   * its own values (`TEXT_REVEAL_DEFAULTS`) — and driven through its exported
   * `normalizeEffects`, `enterOffset` and `resolveEasing`, so the two cannot
   * drift apart. `effects` accepts the same list: fade, slide, blur, scale,
   * tracking.
   */
  effects?: TextRevealEffect[] | string;
  direction?: TextRevealDirection;
  /** How far a glyph travels in `direction`, in px. */
  distance?: number;
  blurAmount?: number;
  scaleFrom?: number;
  /** Frames a glyph takes to arrive. */
  enterDuration?: number;
  easing?: TextRevealEasing;
  /**
   * Cap-to-descender height as a fraction of the frame height.
   *
   * 0.1256, not the 0.139 the reference's raw ink height suggests: measured back
   * from the rendered line width against the reference's at the same frame, mine
   * came out 12.7% wide at 0.139 and 4% narrow at 0.1233, because ink height
   * includes the descender and the face's
   * own metrics differ from the reference's.
   */
  size?: number;
  theme?: Partial<SnapCnTheme>;
  mode?: "light" | "dark";
}

/**
 * `will-change` is right for the Player and wrong for the render — a render
 * draws each frame in a different tab, and a promoted layer hands that tab a
 * stale raster from whatever scale it last drew.
 */
const promoted = getRemotionEnvironment().isRendering
  ? null
  : ({ willChange: "transform" } as const);

/**
 * Hinting bends each glyph so its stems land on whole pixels, so as anything
 * moves the letterforms re-snap and boil. This also forces sub-pixel glyph
 * positioning, which Blink otherwise only enables above a device scale factor of
 * 1 — and a render is exactly 1, so without it every glyph in the morph would
 * land on a whole pixel and the travel would stutter.
 */
const CRISP: CSSProperties = {
  textRendering: "geometricPrecision",
  WebkitFontSmoothing: "antialiased",
};

/** Moderate decelerate. Quint/expo spend frames below half a pixel, which rasterise identically. */
const EASE = Easing.bezier(0.2, 0.6, 0.35, 1);

/**
 * Pair each glyph of `to` with a glyph of `from` that can travel to it.
 *
 * Greedy nearest-unused match on the character itself. It is not the optimal
 * assignment and does not need to be — what the eye reads is *continuity*, that
 * some letters persisted rather than the whole line being replaced, and a
 * nearest match delivers that while an optimal one costs a matrix and looks the
 * same. Unmatched targets fade up in place; unmatched sources fade out in place.
 */
function pairGlyphs(from: string, to: string): (number | null)[] {
  const used = new Set<number>();
  return [...to].map((ch, ti) => {
    let best: number | null = null;
    let bestDist = Infinity;
    for (let fi = 0; fi < from.length; fi += 1) {
      if (used.has(fi) || from[fi] !== ch) continue;
      const dist = Math.abs(fi - ti);
      if (dist < bestDist) {
        bestDist = dist;
        best = fi;
      }
    }
    if (best !== null) used.add(best);
    return best;
  });
}

/** Per-glyph x offsets of a string, measured in the real face at the real size. */
function useGlyphOffsets(
  strings: string[],
  fontSize: number,
  /** Glyphs before this index in string 0 are rendered at 400, the rest at 700. */
  regularUntil: number,
) {
  const ref = useRef<HTMLDivElement>(null);
  const [offsets, setOffsets] = useState<number[][] | null>(null);
  // Every frame of a render is a fresh mount, so a plain effect + state lets the
  // frame be captured *before* the measurement has re-rendered — the glyphs are
  // then placed with no offsets at all and the frame comes out blank or short.
  // `delayRender` holds the capture until the second render has happened.
  const [handle] = useState(() => delayRender("type-morph: measuring glyphs"));

  useLayoutEffect(() => {
    const root = ref.current;
    if (!root) return;
    // `offsetLeft` is layout px and unaffected by transforms — which is exactly
    // why it is the right tool for measuring a line that is about to be
    // transformed. Widths come from the same pass so the caret can sit at the
    // true end of the text rather than at an estimate of it.
    setOffsets(
      [...root.children].map((line) =>
        [...(line as HTMLElement).children].map(
          (g) => (g as HTMLElement).offsetLeft,
        ),
      ),
    );
  }, []);

  // Only once the measured offsets are actually in the tree.
  useLayoutEffect(() => {
    if (offsets) continueRender(handle);
  }, [offsets, handle]);

  const probe = (
    <div
      ref={ref}
      aria-hidden
      style={{
        position: "absolute",
        visibility: "hidden",
        pointerEvents: "none",
        whiteSpace: "pre",
        fontFamily: SANS,
        fontSize,
        letterSpacing: "-0.035em",
        ...CRISP,
      }}
    >
      {strings.map((s) => (
        // biome-ignore lint/suspicious/noArrayIndexKey: fixed list, never reordered
        <div key={s} style={{ whiteSpace: "pre" }}>
          {[...s].map((ch, i) => (
            // biome-ignore lint/suspicious/noArrayIndexKey: glyph position is the identity here
            <span key={i} style={{ display: "inline-block" }}>
              {ch === " " ? " " : ch}
            </span>
          ))}
        </div>
      ))}
    </div>
  );

  return { probe, offsets };
}

/**
 * A headline that types itself, sheds its lead, morphs letter by letter, and
 * ends under a colour flood.
 *
 * Four mechanics on one timeline, each measured off a reference frame by frame
 * (see `timeline.ts` for the signals and the numbers they produced):
 *
 * 1. **Typing.** The line is centre-anchored, so it grows in both directions
 *    rather than running to the right. Freshly landed glyphs arrive in the
 *    accent colour and cool to ink over four frames, which is what gives the
 *    typing a moving warm edge instead of a hard cursor.
 * 2. **The cut.** The lead is removed in a single frame, not animated out. What
 *    *is* animated is the slide back to centre that follows it.
 * 3. **The morph.** Glyphs shared between the two phrases travel from where they
 *    were to where they belong; the rest cross-fade in place.
 * 4. **The flood.** Two flat colours, four frames each.
 *
 * Every glyph position is measured in the real face at the real size behind a
 * hidden probe, because a morph built on estimated advance widths lands each
 * letter a pixel or two off and reads as a wobble.
 */
export function TypeMorph({
  lead = "Not just ",
  emphasis = "communicator.",
  morphTo = "something more.",
  finally_ = "more.",
  wordOnFlood = false,
  accent,
  background,
  ink,
  effects = TEXT_REVEAL_DEFAULTS.effects,
  direction = TEXT_REVEAL_DEFAULTS.direction,
  distance = TEXT_REVEAL_DEFAULTS.distance,
  blurAmount = TEXT_REVEAL_DEFAULTS.blurAmount,
  scaleFrom = TEXT_REVEAL_DEFAULTS.scaleFrom,
  enterDuration = TEXT_REVEAL_DEFAULTS.enterDuration,
  easing = TEXT_REVEAL_DEFAULTS.easing,
  flood = false,
  size = 0.1256,
  theme,
  mode,
}: TypeMorphProps) {
  const frame = useCurrentFrame();
  const { height, width } = useVideoConfig();
  const t = useSnapCnTheme(theme, mode);
  const hot = accent ?? t.primary;
  const paper = background ?? t.background;
  const type = ink ?? t.foreground;
  const fontSize = height * size;

  const typed = lead + emphasis;
  const { probe, offsets } = useGlyphOffsets(
    [typed, emphasis, morphTo, finally_],
    fontSize,
    lead.length,
  );

  // ── the timeline ──────────────────────────────────────────────────────────
  //
  // Absolute frame numbers, measured, not derived from each other. Deriving them
  // meant one wrong constant early shifted everything after it.

  /** The frame a given character lands on. The last one is held back — a beat. */
  const landingOf = (i: number) =>
    TYPE_START +
    i * FRAMES_PER_CHAR +
    (i === typed.length - 1 ? FINAL_CHAR_HOLD : 0);

  const shownChars = (() => {
    let n = 0;
    for (let i = 0; i < typed.length; i += 1)
      if (frame >= landingOf(i)) n = i + 1;
    return n;
  })();

  const floodAt = CUT2_AT + 1;
  const floodBAt = floodAt + FLOOD_STAGE_FRAMES;

  const phase =
    flood && frame >= floodAt
      ? "flood"
      : frame >= CUT2_AT
        ? "final"
        : frame >= MORPH_FROM
          ? "morph"
          : frame >= CUT_AT
            ? "slide"
            : "type";

  const floodColor =
    flood && frame >= floodAt
      ? frame >= floodBAt
        ? flood[1]
        : flood[0]
      : null;

  const centre = width / 2;

  /**
   * The line's horizontal offset — ONE continuous function of frame.
   *
   * The reference does not cut and then move; it moves continuously and the cut
   * only changes what is drawn. A single 16-frame cubic-bezier fits all 17
   * frames of the re-centring, straight through the cut, to 0.067px. Modelling
   * it as "drift, cut, slide" fits the same curve twice and puts a seam where
   * the reference has none.
   *
   * The travel is not a fixed distance — it is however far off-centre the
   * emphasis happens to sit inside the typed line, which the measured probe
   * already knows. On the reference that works out to 184.4px right of centre on
   * a 1400px frame; on any other phrase it is whatever that phrase needs.
   */
  const slideProgress = interpolate(frame, [SLIDE_FROM, SLIDE_TO], [0, 1], {
    easing: Easing.bezier(...SLIDE_BEZIER),
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  /** The exit: geometric per-frame velocity. Persists past the cut it precedes. */
  //
  // It stops at the cut. The reference carries the drifted position into what
  // the cut leaves behind, but the final phrase here is centred by choice, and a
  // drift still applied to it would drag a centred phrase off to the left — 300px
  // by the last frame.
  const exitDrift =
    frame <= EXIT_FROM || frame >= CUT2_AT
      ? 0
      : (-EXIT_COEFF * (EXIT_RATIO ** (frame - EXIT_FROM) - 1) * width) / 1400;

  /**
   * A glyph's entrance — `text-reveal`'s, evaluated with its own functions.
   *
   * `normalizeEffects` decides which channels are live, `enterOffset` gives the
   * travel for the chosen direction, and `resolveEasing` supplies the curve.
   * Nothing here re-implements any of it; if `text-reveal`'s "smooth" changes,
   * this changes with it, which is the point of taking the component's animation
   * rather than a copy of it.
   *
   * Worth knowing: text-reveal's default "smooth" is `bezier(0.22, 1, 0.36, 1)`,
   * the quint-out this repo's motion notes measured as spending 5 of 14 frames
   * moving under half a pixel — frames that rasterise identically. That is the
   * component's shipped curve and it is what "the exact animation" means, so it
   * is the default here too; `easing="snappy"` is the steadier alternative.
   */
  const active = normalizeEffects(effects);
  const ease = resolveEasing(easing);
  const travel = enterOffset(direction, distance);

  const entrance = (age: number) => {
    const t = ease(Math.min(1, Math.max(0, age) / enterDuration));
    const away = 1 - t;
    return {
      scale: active.includes("scale") ? scaleFrom + (1 - scaleFrom) * t : 1,
      blur: active.includes("blur") ? blurAmount * away : 0,
      dx: active.includes("slide") ? travel.x * away : 0,
      dy: active.includes("slide") ? travel.y * away : 0,
      opacity: active.includes("fade") ? t : 1,
    };
  };

  /** One glyph, absolutely placed, so nothing reflows as the line changes. */
  const glyph = (
    key: string,
    ch: string,
    x: number,
    lineWidth: number,
    style: CSSProperties,
    enter?: ReturnType<typeof entrance>,
  ) => (
    <span
      key={key}
      style={{
        position: "absolute",
        left: centre - lineWidth / 2 + x,
        top: 0,
        whiteSpace: "pre",
        ...(enter ? { opacity: enter.opacity } : null),
        ...(enter && (enter.scale !== 1 || enter.dy !== 0 || enter.dx !== 0)
          ? {
              // Pivoted on the glyph's centre. That is what the reference does —
              // its first glyph's top edge moves down 6px and its bottom edge up
              // 7px as it shrinks, which is only true of a centre pivot. It is
              // also the pivot this repo's motion rules warn against, because a
              // moving baseline climbs the pixel grid; the settle is five frames
              // and 13px, and matching the reference is the job here.
              transform: `translate(${enter.dx.toFixed(2)}px, ${enter.dy.toFixed(2)}px) scale(${enter.scale.toFixed(4)})`,
              transformOrigin: "50% 50%",
            }
          : null),
        ...(enter && enter.blur > 0.05
          ? { filter: `blur(${enter.blur.toFixed(2)}px)` }
          : null),
        ...style,
      }}
    >
      {ch === " " ? " " : ch}
    </span>
  );

  let content: React.ReactNode = null;

  if (offsets) {
    const [typedX, emphX, morphX, finalX] = offsets;
    const widthOf = (xs: number[], str: string) =>
      (xs[str.length - 1] ?? 0) + fontSize * 0.34;

    const wTyped = widthOf(typedX, typed);
    const wEmph = widthOf(emphX, emphasis);
    const wMorph = widthOf(morphX, morphTo);

    // Where the emphasis sits inside the typed line. The slide carries the whole
    // line, so both the typed phase and the post-cut phase read the same offset.
    const emphInTyped = typedX[lead.length] - wTyped / 2 + wEmph / 2;

    if (phase === "type" || phase === "slide") {
      const cut = frame >= CUT_AT;
      const from = cut ? lead.length : 0;
      const upto = cut ? typed.length : shownChars;
      // Before the slide begins the line is centred on itself; during it, the
      // emphasis is carried to centre and the lead rides along.
      // 0 at the start of the slide, -emphInTyped at the end: the line travels
      // exactly far enough to bring the emphasis to centre, and nothing jumps
      // when the lead stops being drawn part-way through.
      const dx = -emphInTyped * slideProgress;
      content = [...typed].slice(from, upto).map((ch, k) => {
        const i = from + k;
        const age = frame - landingOf(i);
        const cool = interpolate(
          age,
          [0, COOL_SPAN * FRAMES_PER_CHAR],
          [GLYPH_ENTER_TINT, 1],
          { extrapolateLeft: "clamp", extrapolateRight: "clamp" },
        );
        return glyph(
          `t${i}`,
          ch,
          typedX[i] + dx,
          wTyped,
          {
            color: mixOklch(hot, type, cool),
            fontWeight: i < lead.length ? 400 : 700,
          },
          entrance(age),
        );
      });
    } else if (phase === "morph") {
      const p = interpolate(frame, [MORPH_FROM, MORPH_TO], [0, 1], {
        easing: EASE,
        extrapolateLeft: "clamp",
        extrapolateRight: "clamp",
      });
      const w = interpolate(p, [0, 1], [wEmph, wMorph]);
      const pairs = pairGlyphs(emphasis, morphTo);
      const matched = new Set(pairs.filter((x): x is number => x !== null));
      content = [
        ...[...emphasis].map((ch, i) =>
          matched.has(i)
            ? null
            : glyph(`x${i}`, ch, emphX[i] + (wEmph - w) / 2, w, {
                color: type,
                fontWeight: 700,
                opacity: interpolate(p, [0, 0.45], [1, 0], {
                  extrapolateRight: "clamp",
                }),
              }),
        ),
        ...[...morphTo].map((ch, i) => {
          const src = pairs[i];
          const to = morphX[i] + (wMorph - w) / 2;
          if (src === null) {
            return glyph(`n${i}`, ch, to, w, {
              color: type,
              fontWeight: 700,
              opacity: interpolate(p, [0.55, 1], [0, 1], {
                extrapolateLeft: "clamp",
                extrapolateRight: "clamp",
              }),
            });
          }
          const fromX = emphX[src] + (wEmph - w) / 2;
          return glyph(`m${i}`, ch, interpolate(p, [0, 1], [fromX, to]), w, {
            color: type,
            fontWeight: 700,
          });
        }),
      ].filter(Boolean);
    } else {
      // The final phrase, CENTRED — it does not inherit the drifted position.
      const w = widthOf(finalX, finally_);
      const hidden = phase === "flood" && !wordOnFlood;
      content = hidden
        ? []
        : [...finally_].map((ch, i) =>
            glyph(`f${i}`, ch, finalX[i], w, {
              fontWeight: 700,
              color: floodColor
                ? mixOklch(floodColor, t.background, 0.92)
                : type,
              opacity: 1,
            }),
          );
    }
  }

  // The caret sits at the end of what has been typed, and stops at the cut.
  const caretAlive = frame < CUT_AT && !floodColor;
  let caretX = centre;
  if (offsets) {
    const [typedX] = offsets;
    const wNow = (typedX[Math.max(0, shownChars - 1)] ?? 0) + fontSize * 0.34;
    const wFull = (typedX[typed.length - 1] ?? 0) + fontSize * 0.34;
    caretX = centre - wFull / 2 + wNow;
  }

  return (
    <AbsoluteFill
      style={{
        background: floodColor ?? paper,
        fontFamily: SANS,
        ...CRISP,
      }}
    >
      {probe}
      <div
        style={{
          position: "absolute",
          top: "50%",
          left: 0,
          right: 0,
          height: 0,
          fontSize,
          lineHeight: 1,
          letterSpacing: "-0.035em",
          transform: `translate(${exitDrift.toFixed(2)}px, ${-fontSize * 0.36}px)`,
          ...promoted,
        }}
      >
        {content}
        {caretAlive && !floodColor ? (
          <span
            aria-hidden
            style={{
              position: "absolute",
              left: caretX,
              top: fontSize * 0.06,
              width: fontSize * 0.085,
              height: fontSize * 0.78,
              background: hot,
              opacity: interpolate(frame, [TYPE_START, CUT_AT], [0.95, 0.55], {
                extrapolateLeft: "clamp",
                extrapolateRight: "clamp",
              }),
            }}
          />
        ) : null}
      </div>
    </AbsoluteFill>
  );
}

export default TypeMorph;

/**
 * Every number here was measured off the reference recording, frame by frame.
 *
 * Source: a 30fps screen recording, 89 frames, 1400x762. Frames were cut at
 * 30fps and each reduced to signals — the bounding box of ink (a green-channel
 * threshold isolates glyph cores and rejects the violet bloom, which a mean-RGB
 * threshold does not), the centroid and count of chromatic pixels, and mean
 * luminance. Curves were then fitted against exponential, polynomial and
 * cubic-bezier families and the residuals compared, rather than a shape being
 * assumed.
 *
 * Frame numbers below are 0-based composition frames. The source's `g001.png` is
 * frame 0.
 */

export const FPS = 30;

// ── Typing ───────────────────────────────────────────────────────────────────

/** Frame the first character lands. */
export const TYPE_START = 1;

/**
 * Frames per character: 1.5467, a constant rate.
 *
 * Measured landing frames for the reference's 22 glyphs are
 * 1,3,4,6,8,9,11,12,14,15,17,19,20,22,23,25,26,27,29,31,32,39 — the first 21 fit
 * one constant rate to 0.28 frames mean error, and a quadratic barely improves
 * on that (0.25), so there is no ease on the cadence.
 *
 * Note this is a *character* rate, not a caret speed: px/frame across the
 * landings ranges from 9.5 to 87 because glyph widths differ.
 */
export const FRAMES_PER_CHAR = 1.5467;

/**
 * The final character is held back — it is a beat, not a typo.
 *
 * The last glyph of the reference's line is its full stop, and it lands on frame
 * 39 where the constant rate predicts 34. Five frames of nothing, then the
 * period. Averaging it into the rate is what made every earlier version's typing
 * drift against the reference through the second half of the line.
 */
export const FINAL_CHAR_HOLD = 5;

/** Glyph arrival, measured on the first glyph: 65x86px at landing, 57x73 settled. */
export const GLYPH_ENTER_SCALE = 1.178;
export const GLYPH_SETTLE_FRAMES = 5;

/**
 * How far toward ink a glyph already is when it lands.
 *
 * Not zero. The reference's arriving glyphs run #292541 -> #252221 -> #232120
 * across their first three frames: a near-black with a violet cast. The light
 * violet belongs to the caret, not the type — starting glyphs at the full caret
 * colour left them invisible against the page for their first frames.
 */
export const GLYPH_ENTER_TINT = 0.78;

/** Trailing glyphs mid-cool at any moment. */
export const COOL_SPAN = 2;

// ── The slide ────────────────────────────────────────────────────────────────

/**
 * The re-centring move is ONE continuous curve, and it starts before the cut.
 *
 * This is the correction that mattered most. The obvious reading is "the lead is
 * cut, then what is left slides back to centre", which makes the motion start at
 * the cut. It does not. The line is already moving five frames earlier, and one
 * 16-frame cubic-bezier fits all 17 frames of it — through the cut — to a mean
 * error of 0.067px, max 0.23px.
 *
 * Alternatives on the same data: exponential decay 8.76px, a Remotion spring
 * with five free parameters 2.07px, degree-6 polynomial 1.60px, cubic 6.94px.
 * The bezier is better by two orders of magnitude, so this is not a close call.
 *
 * The consequence for the implementation: **the cut is a visibility change, not
 * a position change.** Residuals across it are +0.080 (before) and -0.108
 * (after) — nothing jumps. Earlier versions modelled a "pre-cut drift" and a
 * separate slide, which is the same curve described as two and fitted twice.
 */
export const SLIDE_FROM = 39;
export const SLIDE_TO = 55;
export const SLIDE_BEZIER = [0.3438, 0.0294, 0.032, 0.9269] as const;

/** The lead stops being drawn here. Position is unaffected — see `SLIDE_BEZIER`. */
export const CUT_AT = 44;

// ── The morph ────────────────────────────────────────────────────────────────

export const MORPH_FROM = 56;
export const MORPH_TO = 67;

// ── The exit ─────────────────────────────────────────────────────────────────

/**
 * The exit drift: geometric per-frame velocity, i.e. an exponential ease-in.
 *
 * Starts at frame 72 — the frames before it are static to within 0.005px, and
 * frame 73 is the first displaced one at 0.73px. Sub-pixel displacements are
 * 0.73, 1.99, 3.70, 6.05, 9.76, 16.28, 30.03, 54.2; the integer bounding box
 * reads those as 1,2,3,7,9,16,29,54 because motion blur erodes a thresholded
 * edge, which is why an earlier hand-fit had both the start frame and the first
 * step wrong.
 *
 * Fit: 0.36px mean error. Quadratic is 8.60px, cubic 3.42px, easeInQuart 1.72px.
 */
export const EXIT_FROM = 72;
export const EXIT_RATIO = 1.76456;
export const EXIT_COEFF = 1.3194;

/** The cut to the final phrase. */
export const CUT2_AT = 81;

// ── The ending ───────────────────────────────────────────────────────────────

/** Frames the final phrase is held when there is no flood. */
export const FINAL_HOLD = 12;
/** Each flood stage. Both are single-frame cuts to a flat colour, not ramps. */
export const FLOOD_STAGE_FRAMES = 4;

/**
 * The reference's own palette. Component defaults come from the design system;
 * these are here so the doc and the preview can quote what was measured.
 *
 * The page is #f7f7f7 for the whole non-flood run and never changes — the
 * per-channel median is exactly 247 on 79 of 82 frames, reading 249 only where
 * a grain overlay peaks.
 */
export const REFERENCE = {
  page: "#f7f7f7",
  ink: "#1f1f1f",
  caret: "#b3a9f9",
  floodA: "#8575fa",
  floodB: "#4931f2",
} as const;

/** Total frames, end to end. */
export function totalFrames(hasFlood = false): number {
  return CUT2_AT + 1 + (hasFlood ? FLOOD_STAGE_FRAMES * 2 : FINAL_HOLD);
}
